def skill():
    a = Symbol('a')
    a = solve(3 + 2*a - 9, a)[0]
    x, r = Symbol('x'), Symbol('r')
    f = (x - a)**2*(x + r) - 2*x + 9
    rr = solve(f.subs(x, 0), r)[0]
    return f.subs(r, rr).subs(x, 1)

def standard():
    x, a, p, q = symbols('x a p q')
    f = x**3 + p*x**2 + q*x
    sol = solve([f.subs(x, a) - 3, diff(f, x).subs(x, a) + 2, 3 + 2*a - 9], [a, p, q], dict=True)
    assert len(sol) == 1
    return f.subs(sol[0]).subs(x, 1)

def unique():
    return [standard()]
